# Generated by build.py from recipe.yml for recipe http-require-a-proxy-login. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--user', 'web:site-pw', 'http://127.0.0.1:8080/', '--proxy', 'http://127.0.0.1:8081/', '--proxy', 'https://127.0.0.1:8082/', '--cert', 'server.pem', '--key', 'server.key', '-U', 'app:proxy-pw' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -x http://127.0.0.1:8081/ --proxy-digest -U app:proxy-pw --digest -u web:site-pw http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
